        runs = []
        i = 0
        while i < len(line):
            j = i + 1
            while j < len(line) and line[j] == line[i]:
                j += 1
            runs.append((line[i], i, j - 1))
            i = j
        return runs

    # Find equal-length matching colored runs on opposite borders.
    pairs = []
    for side_a, line_a, side_b, line_b in (
        ('top', grid[0], 'bottom', grid[-1]),
        ('left', [grid[r][0] for r in range(h)], 'right', [grid[r][-1] for r in range(h)]),
    ):
        for ca, a0, a1 in edge_runs(line_a):
            if ca == bg: continue
            for cb, b0, b1 in edge_runs(line_b):
                if ca == cb and a1-a0 == b1-b0:
                    pairs.append((side_a, ca, a0, a1, side_b, b0, b1))
    if not pairs:
        return out

    # Select the matched edge pair that has interior marker(s) aligned to one of its spans.
    chosen = None
    best = -1
    for pair in pairs:
        sa, edge_color, a0, a1, sb, b0, b1 = pair
        horiz = sa in ('top', 'bottom')
        span_a, span_b = (a0, a1), (b0, b1)
