                    v = grid[r][c]
                    coord = c if horiz else r
                    if v != bg and v != edge_color and lo <= coord <= hi:
                        markers.append((r, c, v))
            if len(markers) > best:
                best = len(markers)
                chosen = (pair, source_index, markers)
    if chosen is None or best <= 0:
        return out

    (sa, edge_color, a0, a1, sb, b0, b1), source_index, markers = chosen
    horiz = sa in ('top', 'bottom')
    source_lo, source_hi = ((a0, a1) if source_index == 0 else (b0, b1))
    target_lo, target_hi = ((b0, b1) if source_index == 0 else (a0, a1))
    source_side = sa if source_index == 0 else sb
    target_side = sb if source_index == 0 else sa

    for r, c, color in markers:
        coord = c if horiz else r
        offset = coord - source_lo
        target_coord = target_lo + offset
        out[r][c] = 4
        # Extend the marker's color from its location toward its matched edge.
        if horiz:
            step = -1 if source_side == 'left' else 1
            x = c + step
            while 0 <= x < w and grid[r][x] != edge_color:
                out[r][x] = color
                x += step
            # The corresponding offset in the opposite edge segment is a full transverse ray.
            if 0 <= target_coord < w:
                for rr in range(1, h-1):
                    out[rr][target_coord] = color
        else:
            step = -1 if source_side == 'top' else 1
            x = r + step
            while 0 <= x < h and grid[x][c] != edge_color:
                out[x][c] = color
                x += step
            if 0 <= target_coord < h:
                for cc in range(1, w-1):
                    out[target_coord][cc] = color
    return out
