def transform(grid):
    """Project marker rays between equal-length matching runs on opposite edges."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    vals = [v for row in grid for v in row]
    counts = {v: vals.count(v) for v in set(vals)}
    background = max(counts, key=counts.get)

    def runs(line):
        result = []
        i = 0
        while i < len(line):
            j = i
            while j + 1 < len(line) and line[j + 1] == line[i]:
                j += 1
            result.append((line[i], i, j))
            i = j + 1
        return result

    pairs = []
    for side1, edge1, side2, edge2 in (
        ('top', grid[0], 'bottom', grid[-1]),
        ('left', [grid[r][0] for r in range(h)], 'right', [grid[r][-1] for r in range(h)]),
    ):
        for color1, a, b in runs(edge1):
            for color2, x, y in runs(edge2):
                if color1 == color2 and b - a == y - x:
                    pairs.append((side1, side2, color1, a, b, x, y))

    for s1, s2, edge_color, a, b, x, y in pairs:
        horizontal = s1 == 'top'
        for side, lo, hi, other_lo in ((s1, a, b, x), (s2, x, y, a)):
            markers = []
            for r in range(h):
                for c in range(w):
                    v = grid[r][c]
                    coord = c if horizontal else r
                    if lo <= coord <= hi and v != background and v != edge_color:
                        markers.append((r, c, v, coord - lo))
            for r, c, color, offset in markers:
                out[r][c] = 4
                if horizontal:
                    # Paint from the point toward the matching horizontal edge.
                    step = -1 if side == 'top' else 1
                    rr = r + step
                    while 0 < rr < h - 1:
                        out[rr][c] = color
                        rr += step
                    # Corresponding offset at the opposite edge casts a full column.
                    col = other_lo + offset
                    if 0 <= col < w:
                        for rr in range(1, h - 1):
                            out[rr][col] = color
                else:
                    step = -1 if side == 'left' else 1
                    cc = c + step
                    while 0 < cc < w - 1:
                        out[r][cc] = color
                        cc += step
                    row = other_lo + offset
                    if 0 <= row < h:
                        for cc in range(1, w - 1):
                            out[row][cc] = color
            # Process first matching pair that contains aligned markers.
            if markers:
                return out
    return out
