            while j + 1 < len(line) and line[j + 1] == line[i]:
                j += 1
            groups.append((line[i], i, j))
            i = j + 1
        return groups

    # Candidate corresponding segments on opposing borders must share a
    # non-background color. Their shared offsets map dots from one edge to the other.
    candidates = []
    edge_pairs = [
        ('top', grid[0], 'bottom', grid[-1]),
        ('left', [grid[r][0] for r in range(h)], 'right', [grid[r][-1] for r in range(h)]),
    ]
    for side_a, edge_a, side_b, edge_b in edge_pairs:
        horizontal = side_a == 'top'
        for color_a, a0, a1 in runs(edge_a):
            if color_a == background:
                continue
            for color_b, b0, b1 in runs(edge_b):
                if color_a != color_b:
                    continue
                for side, lo, hi, opposite_lo, opposite_hi in (
                    (side_a, a0, a1, b0, b1),
                    (side_b, b0, b1, a0, a1),
                ):
                    pts = []
                    for r in range(h):
                        for c in range(w):
                            pos = c if horizontal else r
                            v = grid[r][c]
                            off = pos - lo
                            if lo <= pos <= hi and opposite_lo <= opposite_lo + off <= opposite_hi:
                                if v != background and v != color_a:
                                    pts.append((r, c, v, off))
                    if pts:
                        candidates.append((len(pts), horizontal, side, color_a, pts))
    if not candidates:
        return out

    _, horizontal, source_side, edge_color, points = max(candidates, key=lambda x: x[0])
    # Determine the paired run and corresponding start for the chosen source side.
    # Re-find it using the marker coordinates and matched border color.
    if horizontal:
        opposite_edge = grid[-1] if source_side == 'top' else grid[0]
        source_edge = grid[0] if source_side == 'top' else grid[-1]
