        source_edge = [grid[r][0] for r in range(h)] if source_side == 'left' else [grid[r][-1] for r in range(h)]
    src_runs = [x for x in runs(source_edge) if x[0] == edge_color]
    opp_runs = [x for x in runs(opposite_edge) if x[0] == edge_color]
